### 核心

- 設定寫在nuxt.config.ts中的vite屬性
- 記得要「rewrite」路徑
- 請用`http`而非https

### 實作

- nuxt.config.ts

    ```tsx
    import { defineNuxtConfig } from 'nuxt';

    // https://v3.nuxtjs.org/docs/directory-structure/nuxt.config
    export default defineNuxtConfig({
        vite: {
            server: {
                proxy: {
                    '/api-main': {
                        target: 'http://your-api-here',
                        ws: true,
                        changeOrigin: true,
                        rewrite: (path) => path.replace(/^\/api-main/, ''), 
    										// rewrite這個proxy的路徑
                    },
                },
            },
        },
    });
    ```


